#!/usr/bin/env python3
"""PAOFLOW phonon-limited carrier mobility (SERTA / MRTA) on EPW's coarse coupling (generated by paoflow_gen.py).

State-resolved electron-phonon scattering rates 1/tau_nk(T) of the states near
the band edges (semiconductors, insulators) or the Fermi level (metals), in the
self-energy (SERTA) and momentum-relaxation (MRTA) relaxation-time
approximations, with the coupling, the electrons, their velocities and the
phonons all interpolated in the PAO basis; then the k-resolved conductivity,
carrier densities, electron and hole mobilities and Seebeck coefficient on the
same dense grid.

The coarse electron-phonon matrix elements come from EPW (``epbwrite = .true.``),
exactly as for the Eliashberg workflow.  paoflow-gen wrote the QE/EPW inputs in
two run directories:

    phonon/scf.in, phonon/ph.in               pw.x scf + ph.x DFPT (irreducible q)
    epw/nscf.in, epw/epw.in, epw/write_ukk.py   pw.x nscf (full k list) + epw.x

Run them in this order:

    cd phonon
    mpirun -np N pw.x -in scf.in > scf.out
    mpirun -np N ph.x -in ph.in  > ph.out
    python3 /path/to/q-e/EPW/bin/pp.py      # collects dvscf/patterns/dyn into save/
    cd ../epw
    mkdir -p Si2.save          # the nscf starts from the scf charge density
    cp ../phonon/Si2.save/{charge-density.dat,data-file-schema.xml} Si2.save/
    mpirun -np N pw.x -in nscf.in > nscf.out
    python3 write_ukk.py                    # Si2.ukk (+ empty .bvec/.mmn stubs)
    mpirun -np N epw.x -nk N -in epw.in > epw.out   # writes Si2.epb*, one file per pool
    cd ..
    mpirun -np N python mobility.py         # PAO interpolation -> 1/tau_nk, mobilities
    python plot_mobility.py

Outputs (OUTPUTDIR/mobility/): mobility.dat (T, chemical potential, n_e, n_h,
SERTA and MRTA electron/hole mobilities in cm^2/(V s), conductivities, Seebeck),
rates_<T>K.dat (energy, SERTA and MRTA rates of the window states),
carrier_scattering.npz (all state-resolved arrays) and scattering_rates.npz
(the transport-weighted rate versus energy for PAOFLOW's Boltzmann transport):

    from PAOFLOW.boltzmann.scattering_channels import EnergyResolvedRate
    eph = EnergyResolvedRate.from_npz('OUTPUTDIR/mobility/scattering_rates.npz', 'mrta')
    pf.transport(tmin=300, tmax=300, nt=1, scattering_channels=[eph, 'impurity'])

Its energies are on the PAO energy scale of the Hamiltonian used (that of
PAOFLOW's E_k on ELECTRONS_SAVE when set, else on SAVEDIR), so the Boltzmann run
must use that QE save (otherwise align the band edges with energy_shift_ev),
and its temperatures within TEMPS_K.

Carriers: DOPING_CM3 > 0 adds electrons (n type), < 0 holes (p type), 0 gives
the intrinsic carriers; the mobilities do not depend on the carrier density in
the non-degenerate regime.  A scissor (TARGET_GAP_EV, optionally Varshni)
corrects the carrier statistics only: the rates involve intraband energy
differences and are unchanged.  Not included: the long-range (Frohlich) and
dynamical-quadrupole couplings (polar materials raise; for Si-like crystals the
missing quadrupoles overestimate the acoustic intravalley scattering at small q),
the iterative Boltzmann solution (MRTA is usually close to it), and
impurity scattering.  Converge NK_DENSE = NQ_DENSE (mobilities typically need
>= 48^3) and SMEARING_EV together.

ELECTRONS_SAVE (--electrons-save) takes the band energies and eigenvectors from
the PAO Hamiltonian of an eACBN0 (DFT+U+V, ortho-atomic) nscf of the same
crystal in the same PAO basis, keeping the DFPT/EPW coupling in the orbital
basis (ph.x and epw.x cannot use U+V or ortho-atomic projectors): the gap, the
masses and the carrier statistics are then the eACBN0 ones without a scissor,
and --varshni without a target applies the Varshni shift relative to that gap.
Not included: the Hubbard contribution to the coupling (dV_Hub/du).

SCREENING_EPS (--screening-eps) corrects the DFT overscreening of the coupling
as Ponce, Margine and Giustino, PRB 97, 121201(R) (2018): every matrix element
is multiplied by eps_DFT(|q|)/eps(|q|), the ratio of two Resta model dielectric
functions with the DFPT static dielectric constant (stored in the .epb files,
or SCREENING_EPS_DFT) and the target one, e.g. the measured value (Si: 11.94).
"""

import argparse
import os
import sys

from mpi4py import MPI

from PAOFLOW.elphon.carrier_scattering import (
    carrier_scattering_dense_q,
    rta_transport,
    write_mobility_outputs,
)
from PAOFLOW.elphon.coupling_screening import screening_report
from PAOFLOW.elphon.elph_bloch import atom_masses
from PAOFLOW.elphon.pao_electrons import (
    check_same_pao_basis,
    format_hubbard_info,
    pao_hamiltonian_from_save,
)
from PAOFLOW.elphon.phonon_assisted_absorption import varshni_gap, varshni_shift

# ----------------------------------------------------------------------- #
# Configuration  (edit freely -- masses / NELEC are system-specific)      #
# ----------------------------------------------------------------------- #
HERE = os.path.dirname(os.path.abspath(__file__))
PREFIX = 'Si2'
COUPLING_SOURCE = (
    'dfpt'  # 'dfpt': native vertex from ph.x's dvscf + the nscf save; 'epw': EPW's .epb files
)
PHONON_DIR = os.path.join(HERE, 'phonon')  # ph.x run directory (_ph0/, Si2.dyn*) or its pp.py save/
EPW_DIR = os.path.join(
    HERE, 'epw'
)  # nscf save (Si2.save); with COUPLING_SOURCE='epw' also Si2.epb*, Si2.ukk
SAVEDIR = os.path.join(HERE, 'epw/Si2.save')  # the nscf save on the coarse k-grid
UNFOLD_KPOINTS = False  # True if epw/nscf.in used 'K_POINTS automatic' (irreducible wedge) instead of the explicit list
COUPLING_DIR = PHONON_DIR if COUPLING_SOURCE == 'dfpt' else EPW_DIR
BASISDIR = os.path.join(HERE, 'BASIS_PS')  # paoflow-genbasis-ps --pseudo <upf> --out <BASISDIR>
OUTPUTDIR = os.path.join(HERE, 'output')

COARSE_GRID = (6, 6, 6)  # nscf k-grid (EPW nk1..3)
QGRID = (3, 3, 3)  # ph.x / EPW q-grid (nq1..3); must divide COARSE_GRID
MASSES_AMU = [28.085]  # mass of each species (amu), ATOMIC_SPECIES order (EPW amass)
NELEC = 8  # valence electrons (locates the gap)
PTHR = 0.95  # projectability threshold
PROJECTOR = (
    'internal'  # 'internal' (BASISDIR tables) or 'projwfc' (projwfc.x projections of the save)
)
SAVE_OVERLAPS = False  # projwfc overlaps (projwfc projector only)
NK_DENSE = 48  # dense electron grid (EPW nkf1..3)
NQ_DENSE = 48  # dense phonon grid (EPW nqf1..3); NK_DENSE % NQ_DENSE == 0
TEMPS_K = [200.0, 250.0, 300.0, 350.0, 400.0, 500.0]  # temperatures (K)
DOPING_CM3 = 0.0  # net doping (cm^-3): > 0 n type, < 0 p type, 0 intrinsic
WINDOW_EV = 0.3  # states within WINDOW_EV of the band edges (EPW fsthick)
SMEARING_EV = 0.01  # energy-conserving delta smearing (EPW degaussw)
# Scissor of the carrier statistics: target indirect gap (eV), optionally T dependent.
TARGET_GAP_EV = None  # e.g. 1.17 (Si, 0 K); None = DFT gap
VARSHNI = None  # (alpha eV/K, beta K): E_g(T) = E0 - alpha T^2 / (T + beta), E0 = target
# eACBN0 electrons: QE save of a DFT+U+V (ortho-atomic) nscf of the same crystal with the SAME
# pseudopotential, BASIS tables, configuration and PTHR.  Its PAO Hamiltonian gives the band
# energies and eigenvectors (no 0 K scissor); A, the .epb coupling, the k list and the symmetries
# stay those of SAVEDIR, so the coupling in the orbital basis is the DFPT (PBE) one.
ELECTRONS_SAVE = None  # None = the electrons of SAVEDIR
# Coupling screening (Ponce et al. 2018): g -> g eps_DFT(|q|)/eps(|q|), Resta model dielectric functions.
SCREENING_EPS = None  # target static dielectric constant, e.g. 11.94 (Si, measured); None = DFPT
SCREENING_EPS_DFT = (
    None  # dielectric constant of the DFPT coupling; None = the tensor in the .epb files
)


def pao_electronic_structure(electrons_save=None):
    """PAO projections and Hamiltonian; the Hamiltonian optionally from another save.

    The coupling (the projections A, the .epb files, the k list and the
    symmetries) always comes from SAVEDIR, the nscf EPW read.  With
    ``electrons_save`` (an eACBN0 nscf of the same crystal in the same PAO basis)
    the band energies and eigenvectors are those of its PAO Hamiltonian, while the
    coupling in the orbital basis stays that of the DFPT/EPW run.  Returns the
    projections, HRs, the lattice data (with the orbital centres), the data
    controller of the coupling save and a provenance dict for the outputs.
    """
    options = dict(
        basispath=BASISDIR,
        configuration='standard',
        pthr=PTHR,
        projector=PROJECTOR,
        workpath=HERE,
        outputdir=OUTPUTDIR,
        save_overlaps=SAVE_OVERLAPS,
    )
    # The explicit K_POINTS list of the nscf already spans the whole Brillouin zone; an
    # irreducible-wedge nscf is unfolded to it by symmetry (UNFOLD_KPOINTS).
    coupling = pao_hamiltonian_from_save(
        SAVEDIR, expand_wedge=False, unfold_kpoints=UNFOLD_KPOINTS, verbose=False, **options
    )
    kind = lambda run: run.hubbard['kind'] if run.hubbard else 'PBE'  # noqa: E731
    provenance = {
        'coupling_save': SAVEDIR,
        'electrons_save': '',
        'electrons_dft': kind(coupling),
        'electrons_hubbard': format_hubbard_info(coupling.hubbard),
    }
    if electrons_save is None:
        return (
            coupling.projections,
            coupling.HRs,
            coupling.nscf,
            coupling.data_controller,
            provenance,
        )
    # Same basis (pseudopotentials, BASIS tables, configuration, structure, atom order), or stop.
    electrons = pao_hamiltonian_from_save(electrons_save, keep_projections=False, **options)
    summary = check_same_pao_basis(coupling.data_controller, electrons.data_controller)
    if MPI.COMM_WORLD.Get_rank() == 0:
        print('  electrons from %s: %s' % (electrons_save, format_hubbard_info(electrons.hubbard)))
        print(
            '  same PAO basis as %s (bands with projectability > %g: %s vs %s)'
            % (SAVEDIR, PTHR, summary['bnd'][0], summary['bnd'][1])
        )
    nscf = dict(coupling.nscf, orbital_positions=electrons.nscf['orbital_positions'])
    provenance.update(
        electrons_save=os.path.abspath(electrons_save),
        electrons_dft=kind(electrons),
        electrons_hubbard=format_hubbard_info(electrons.hubbard),
    )
    return coupling.projections, electrons.HRs, nscf, coupling.data_controller, provenance


def scissor_settings(args):
    """Scissor of the carrier statistics: ``(scissor_ev, target_gap_ev, mode)``.

    ``'target'``: TARGET_GAP_EV, optionally temperature dependent (Varshni);
    ``'relative'``: only the Varshni shift -alpha T^2/(T + beta) on top of the
    Hamiltonian's own gap (eACBN0 electrons, or the PBE gap at 0 K); ``'none'``.
    """
    if args.target_gap_ev is not None:
        target = (
            varshni_gap(args.target_gap_ev, *args.varshni) if args.varshni else args.target_gap_ev
        )
        return None, target, 'target'
    if args.varshni:
        return varshni_shift(*args.varshni), None, 'relative'
    return None, None, 'none'


def carrier_scattering(projections, HRs, nscf, args, scissor_ev=None, target_gap_ev=None):
    """SERTA/MRTA rates of the window states on the dense grids."""
    return carrier_scattering_dense_q(
        projections,
        HRs,
        nscf['kpts_cryst'],
        nscf['bg'],
        nscf['at'],
        nscf['alat'],
        nscf['omega'],
        COUPLING_DIR,
        QGRID,
        COARSE_GRID,
        coupling_source=COUPLING_SOURCE,
        save_dir=SAVEDIR,
        masses_amu=atom_masses(MASSES_AMU, nscf['species'], nscf['atom_names']),
        nelec=NELEC,
        nk_dense=args.nk,
        nq_dense=args.nq,
        temps_k=args.temps,
        doping_cm3=args.doping,
        window_ev=args.window_ev,
        smearing_ev=args.smearing_ev,
        scissor_ev=scissor_ev,
        target_gap_ev=target_gap_ev,
        screening_eps=args.screening_eps,
        screening_eps_dft=args.screening_eps_dft,
        sym_rots=nscf['s_cryst'],
        tau_cryst=nscf['tau_cryst'],
        species=nscf['atom_names'],
        orbital_positions=nscf['orbital_positions'],
    )


def report(out, args):
    """Print the mobilities and write the outputs to OUTPUTDIR/mobility."""
    print(
        'PAOFLOW carrier transport (k %d^3, q %d^3, smearing %.3f eV, window %.2f eV):'
        % (args.nk, args.nq, args.smearing_ev, args.window_ev)
    )
    if out['metal']:
        print('  metal: conductivity only')
    else:
        print(
            '  %s gap %.3f eV, doping %.3e cm^-3'
            % (out['electrons_dft'], out['cbm_ev'] - out['vbm_ev'], args.doping)
        )
    if out['electrons_save']:
        print(
            '  band energies and eigenvectors from %s; coupling from %s'
            % (out['electrons_save'], out['coupling_save'])
        )
    if out['scissor_mode'] == 'relative':
        print('  carrier statistics: Varshni shift relative to the Hamiltonian gap')
    print(screening_report(out))
    serta, mrta = rta_transport(out, 'serta'), rta_transport(out, 'mrta')
    print(
        '    T (K)  mu_F (eV)   n_e (cm^-3)   n_h (cm^-3)   mobility e / h (cm^2/Vs): '
        'SERTA             MRTA'
    )
    for it, temp in enumerate(out['temps_k']):
        print(
            '  %7.1f  %9.4f  %12.4e  %12.4e  %28.1f / %-8.1f %8.1f / %-8.1f'
            % (
                temp,
                out['fermi_levels_ev'][it],
                out['n_e_cm3'][it],
                out['n_h_cm3'][it],
                serta['mobility_e'][it],
                serta['mobility_h'][it],
                mrta['mobility_e'][it],
                mrta['mobility_h'][it],
            )
        )
    for path in write_mobility_outputs(out, os.path.join(OUTPUTDIR, 'mobility')):
        print('  wrote %s' % path)


def main():
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument(
        '--nk', type=int, default=NK_DENSE, help='dense k-grid (default %(default)s)'
    )
    parser.add_argument(
        '--nq', type=int, default=NQ_DENSE, help='dense q-grid (default %(default)s)'
    )
    parser.add_argument('--temps', type=float, nargs='+', default=TEMPS_K, help='temperatures (K)')
    parser.add_argument(
        '--doping',
        type=float,
        default=DOPING_CM3,
        help='net doping (cm^-3; > 0 n type, < 0 p type, 0 intrinsic)',
    )
    parser.add_argument('--window-ev', type=float, default=WINDOW_EV, help='band-edge window (eV)')
    parser.add_argument(
        '--smearing-ev', type=float, default=SMEARING_EV, help='delta smearing (eV)'
    )
    parser.add_argument(
        '--target-gap-ev',
        type=float,
        default=TARGET_GAP_EV,
        help='target indirect gap (eV) of the statistics scissor (0 K with --varshni)',
    )
    parser.add_argument(
        '--electrons-save',
        default=ELECTRONS_SAVE,
        help='QE save of an eACBN0 (DFT+U+V) nscf in the same PAO basis: its PAO '
        'Hamiltonian replaces the PBE one (band energies and eigenvectors)',
    )
    parser.add_argument(
        '--varshni',
        type=float,
        nargs=2,
        default=VARSHNI,
        metavar=('ALPHA', 'BETA'),
        help='temperature-dependent gap E0 - alpha T^2/(T + beta): around the target, '
        'or relative to the Hamiltonian gap without one (Si: 4.73e-4 636)',
    )
    parser.add_argument(
        '--screening-eps',
        type=float,
        default=SCREENING_EPS,
        help='target dielectric constant of the Ponce screening correction of g (Si: 11.94)',
    )
    parser.add_argument(
        '--screening-eps-dft',
        type=float,
        default=SCREENING_EPS_DFT,
        help='DFT dielectric constant of the coupling (default: the .epb tensor)',
    )
    args = parser.parse_args()
    if args.nk % args.nq:
        sys.exit('--nk (%d) must be a multiple of --nq (%d).' % (args.nk, args.nq))
    if not os.path.isdir(SAVEDIR):
        sys.exit('%s not found. Run the pw.x nscf in epw/ first.' % SAVEDIR)
    if COUPLING_SOURCE == 'epw' and not any(
        f.startswith(PREFIX + '.epb') for f in os.listdir(EPW_DIR)
    ):
        sys.exit(
            'No %s.epb* files in %s. Run epw.x with epbwrite = .true. first.' % (PREFIX, EPW_DIR)
        )
    if COUPLING_SOURCE == 'dfpt' and not (
        os.path.isdir(os.path.join(PHONON_DIR, '_ph0'))
        or any('dvscf' in f for f in os.listdir(PHONON_DIR))
    ):
        sys.exit(
            'No ph.x outputs (_ph0/ or *.dvscf_q*) in %s. Run ph.x with fildvscf first.'
            % PHONON_DIR
        )

    projections, HRs, nscf, _, provenance = pao_electronic_structure(args.electrons_save)
    scissor_ev, target_gap_ev, provenance['scissor_mode'] = scissor_settings(args)
    out = carrier_scattering(projections, HRs, nscf, args, scissor_ev, target_gap_ev)
    out.update(provenance)

    # The result is identical on every rank; only rank 0 reports and writes files.
    if MPI.COMM_WORLD.Get_rank() == 0:
        report(out, args)


if __name__ == '__main__':
    main()
